widgets.onValue:
//console.log(value);

try {

  if (value != null) {

    if(value.Type == 'Paths') {

      //send('custom:module', '/stfs', path, 'varPaths', value)

      if (typeof value.Root != 'string') {

        console.log(`varPaths. Root paths is empty (${value.Root})`)
        set('txtLog',get('txtLog')+`varPaths. Root paths is empty (${value.Root})\n`)
        objPaths.Root = ''
      } 
      set('txtPathsRoot',value.Root)

      if (typeof value.Settings != 'string') {

        console.log(`varPaths. Settings paths is empty (${value.Settings})`);
        set('txtLog',get('txtLog')+`varPaths. Settings paths is empty (${value.Settings})\n`);
        value.Settings = 'settings\\'
      }
      set('txtPathsSettings',value.Settings);

      if (typeof value.Scenes != 'string') {

        console.log(`varPaths. Scenes paths is empty (${value.Scenes})`);
        set('txtLog',get('txtLog')+`varPaths. Scenes paths is empty (${value.Scenes})\n`);
        value.Scenes = 'scenes\\'
      }
      set('txtPathsScenes',value.Scenes);



    } else {
      console.log(`Paths object type is incorrect (${value.Type})`);
      set('txtLog',get('txtLog')+`Paths object type is incorrect (${value.Type})\n`);
    }

  } else {
    console.log(`Paths object is incorrect (${value})`);
    set('txtLog',get('txtLog')+`Paths object is incorrect (${value})\n`);
  }

} catch(e) {
  console.log(`error while varPaths.onValue()`)
  console.error(e)
  set('txtLog',get('txtLog')+'error while updating Paths object')
}

//console.log(`received from fs\n${value}`)
var content, sender, recipient, options

try {
  var array = JSON.parse(value)

  //console.log(`parsing value ok`);

  switch(array.length) {
    case 3:
      content = array[0]
      sender = array[1]
      recipient = array[2]
      break;
    case 4:
      content = array[0]
      sender = array[1]
      recipient = array[2]
      options = array[3]
      break;
    default:
  }

  //console.log(`parsing array ok`);

  switch(recipient.value) {
    case 'varPaths':
      //console.log(`"varPaths" case`)
      if (content.Type == 'Paths') {
        set(recipient.value, content, options)
      }
      break;
    default:
  }
} catch(e) {
  console.log(`error while parsing loaded file\n${value}`)
  console.error(e)
}

