//console.log(`/v chan=${value[0]} bus=${value[1]} N=${value[2]} amp=${value[3]}`);
//set('text_12', JSON.stringify(value));

let inputsPageSelected = get('varUIInputsPageSelected');
let inputsOnPage = get('varUIInputsOnPage');
let packAmount = 1;

switch (value[0]) { //CHANNEL TYPE

  case 'p': //POINT

    switch(value[1]) {

      case 'in': //INPUT BUS

        set(`varInput${value[2]}InVM`, value[3]);
        break;

      case 'gn': //GAIN BUS

        set(`varInput${value[2]}GainVM`, value[3]);      
        break;

      case 'ot': //OUT BUS

        set(`varInput${value[2]}OutVM`, [value[3],value[4],value[5],value[6]]);      
        break;

      default:
        break;

    }

    break;

  case 'ii': //MULTIPLE INPUTS

     switch(value[1]) {

      case 'in': //INPUT BUS

        packAmount = value[2];

        for(let i = 1; i < packAmount + 1; i++) {

          set(`varInput${i}InVM`, value[2 + i]);
        }
        break;

      case 'gn': //GAIN BUS

        packAmount = value[2];

        for(let i = 1; i < packAmount + 1; i++) {

          set(`varInput${i}GainVM`, value[2 + i]);
        }
        break;

      case 'ot': //OUT BUS

        packAmount = value[2];

        for(let i = 1; i < packAmount + 1; i++) {

          set(`varInput${i}OutVM`, value[2 + i]);
        }
        break;

    }

    break;

  default:
