        break;

      case 'v': //VOLUME

        if (get(`varInput${num}Volume`) != value[4]) { set(`varInput${num}Volume`, value[4], {script: false}); }

        console.log(`in ${num} volume ${value[4]}`);

        break;

      default:
        break;

    }
    break;

  case 'de': //DECODER
