var num = get('varDecoderSelectedSpeakersAmount');

var x = [];
var y = [];
var r = get('varDecoderSelectedRadius');
var azim = [];
var dist = [];

for (let i = 0; i < num; i++) {
  //
  x[i] = value[ (i + 1) * 2 - 2 ] * r;
  y[i] = value[ (i + 1) * 2 - 1 ] * r;

  azim[i] = Math.atan(-x[i]/Math.abs(y[i]))*180/Math.PI;
  if (y[i] < 0) {

    if (x[i] > 0) { azim[i] = azim[i]+360; }
    azim[i] = 180 - azim[i];
  }

  set(`varDecoderSelectedSpeaker${i+1}Azim`,azim[i], {script: false});

  dist[i] = Math.sqrt(Math.pow(x[i],2) + Math.pow(y[i],2));
  set(`varDecoderSelectedSpeaker${i+1}Dist`,dist[i], {script: false});

  set(`varDecoderSelectedSpeaker${i+1}Delay`, (r - dist[i])/get('varSpeedOfSound')*1000);
}

