var color = get('drpdwnMIDICtrlCh1LCDColor');
var invertUp = get('btnMIDICtrlCh1LCDInvertUp');
var invertDown = get('btnMIDICtrlCh1LCDInvertDown');
var upperText = get('inpMIDICtrlCh1LCDTextUp').toString(10);
var lowerText = get('inpMIDICtrlCh1LCDTextDown').toString(10);
var colorHex = '';
var upperHex = '';
var lowerHex = '';
var lcdByte = '';
var lcdString = 'F0 00 20 32 15 4C 00 ';

console.log(`upperText length ${upperText.length}`);

for( let i = 0; i < upperText.length; i++) {
  //
  upperHex += upperText.charCodeAt(i).toString(16) + ' ';
}

for( let i = 0; i < lowerText.length; i++) {
  //
  lowerHex += lowerText.charCodeAt(i).toString(16) + ' ';
}

for (let i = 7 - upperText.length; i > 0; i--) {
  //
  upperHex += '20 ';
}

for (let i = 7 - lowerText.length; i > 0; i--) {
  //
   lowerHex += '20 ';
}

console.log(`upperText "${upperText}" upperHex "${upperHex}"`);
console.log(`lowerText "${lowerText}" lowerHex "${lowerHex}"`);

console.log(`color ${color}`);
switch(color) {
  //
  case 'Black':
    colorHex = '0';
    break;

  case 'Red':
    colorHex = '1';
    break;

  case 'Green':
    colorHex = '2';
    break;

  case 'Yellow':
    colorHex = '3';
    break;

  case 'Blue':
    colorHex = '4';
    break;

  case 'Magenta':
    colorHex = '5';
    break;

  case 'Cyan':
    colorHex = '6';
    break;

  case 'White':
    colorHex = '7';
    break;

  default:
    break;
}

lcdByte = Number.parseInt(invertDown.toString() + invertUp.toString(),2) + colorHex;
console.log(`lcdByte=${lcdByte}`);

lcdString = lcdString + lcdByte + ' ' + upperHex + lowerHex + 'F7';

send('midi:ctrl', '/sysex', lcdString);
console.log(lcdString);

